from collections import deque

def find_regions_4conn(grid, color):
    h, w = len(grid), len(grid[0])
    visited = set()
    regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == color and (r,c) not in visited:
                region = []
                queue = deque([(r,c)])
                visited.add((r,c))
                while queue:
                    cr, cc = queue.popleft()
                    region.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
                regions.append(region)
    return regions

